import React from 'react';
import CadConfigurator from './components/CadConfigurator';

function App() {
  return (
    <div className="App bg-gray-100 min-h-screen">
      <header className="p-4 bg-blue-900 text-white text-center">
        <h1 className="text-2xl font-bold">UG Project: Beam Generator</h1>
      </header>
      <main className="p-8">
        <CadConfigurator />
      </main>
    </div>
  );
}

export default App;
